// Portraits for the unit cards and the trading post's shopkeeper
// (play-feel spec, "Changed after Jake's playtest of the full build").
//
// Which portraits exist is not hand-set here: `PORTRAIT_LIST`
// (js/ui/portrait-list.js, generated by scripts/portraits.mjs) names
// every WebP under assets/portraits/. `portraitFor(id, mood)` is the
// lookup: the mood portrait `<id>-<mood>` when there is one, else the
// portrait `<id>`, else the character's stamp drawn large — the white
// silhouette (js/ui/silhouettes.js) on its disc, green for animals and
// rust for bots. To add an image, put its PNG in assets/portraits/ and
// run `node scripts/portraits.mjs`; docs/art/portrait-prompts.md says
// how to make the images. An id with no band type gets a plain stamp
// from its first letter rather than throwing.
//
// `portraitFor`, `portraitSpec` and `shopkeeperSpec` are pure;
// `drawPortrait` and `portraitSvg` draw one with the helpers in
// js/ui/svg.js.

import { BAND_TYPES } from '../engine/units.js';
import { el } from './svg.js';
import { silhouettes } from './silhouettes.js';
import { PORTRAIT_LIST } from './portrait-list.js';
import { ANIMAL, ANIMAL_DARK, RUST, STEEL, SOIL_LIGHT, SOIL_DARK, CREAM } from './patterns.js';

/** Where portrait images are kept, relative to index.html. */
export const PORTRAIT_DIR = 'assets/portraits';

/** The moods a portrait can show (scripts/portraits.mjs knows the same
 *  list). `shrewd` and `greedy` are Hazel's in the trading post
 *  (js/ui/shop-view.js). */
/** @type {readonly string[]} */
export const PORTRAIT_MOODS = Object.freeze(['happy', 'surprised', 'sad', 'angry', 'scared', 'shrewd', 'greedy']);

/** A plain portrait's blink frame is `<id>-blink` (js/ui/blink.js). It is
 *  not a mood: it holds only the closed eyes, to lay over the plain one. */
export const BLINK_SUFFIX = '-blink';

/**
 * @param {string} id  a portrait id: a band type id, 'shopkeeper', or
 *   either with a mood ('fox-surprised')
 * @returns {string}
 */
export function portraitFile(id) {
  return `${PORTRAIT_DIR}/${id}.webp`;
}

/** The trading post's keeper: a squirrel, who knows the price of a seed. */
export const SHOPKEEPER = Object.freeze({
  id: 'shopkeeper',
  name: 'Hazel',
  glyph: '🐿️',
});

/**
 * @typedef {{kind: 'image', href: string, alt: string}
 *   | {kind: 'stamp', glyph: string, disc: string, rim: string, alt: string}} PortraitSpec
 */

/**
 * The display name for a portrait id: the band's name, Hazel for the
 * shopkeeper, or the capitalised id.
 * @param {string} id
 * @returns {string}
 */
function nameFor(id) {
  const def = BAND_TYPES[id];
  if (def !== undefined) return def.name;
  if (id === SHOPKEEPER.id) return SHOPKEEPER.name;
  return id === '' ? id : id[0].toUpperCase() + id.slice(1);
}

/**
 * The stamp for a portrait id: the band's stamp, the shopkeeper's
 * squirrel on warm brown, or a plain stamp from the id's first letter.
 * @param {string} id
 * @param {string} alt
 * @returns {PortraitSpec}
 */
function stampFor(id, alt) {
  const def = BAND_TYPES[id];
  if (def !== undefined) {
    const isUs = def.side === 'us';
    return {
      kind: 'stamp',
      glyph: def.glyph,
      disc: isUs ? ANIMAL : RUST,
      rim: isUs ? ANIMAL_DARK : STEEL,
      alt,
    };
  }
  if (id === SHOPKEEPER.id) {
    return { kind: 'stamp', glyph: SHOPKEEPER.glyph, disc: SOIL_LIGHT, rim: SOIL_DARK, alt };
  }
  return {
    kind: 'stamp',
    glyph: id === '' ? '?' : id[0].toUpperCase(),
    disc: ANIMAL,
    rim: ANIMAL_DARK,
    alt,
  };
}

/**
 * The portrait for a character, in a mood when given: the image
 * `<id>-<mood>` when present, else the image `<id>` when present, else
 * the stamp. Never throws for an unknown id.
 * @param {string} id  a band type id, 'shopkeeper', or any other id
 * @param {string} [mood]  one of PORTRAIT_MOODS
 * @param {readonly string[]} [present]  the portrait ids that exist
 * @returns {PortraitSpec}
 */
export function portraitFor(id, mood, present = PORTRAIT_LIST) {
  const alt = nameFor(id);
  if (mood !== undefined && PORTRAIT_MOODS.includes(mood) && present.includes(`${id}-${mood}`)) {
    return { kind: 'image', href: portraitFile(`${id}-${mood}`), alt };
  }
  if (present.includes(id)) return { kind: 'image', href: portraitFile(id), alt };
  return stampFor(id, alt);
}

/**
 * The portrait for a band type: its image, or its stamp.
 * @param {string} typeId
 * @param {readonly string[]} [present]  the portrait ids that exist
 * @returns {PortraitSpec}
 */
export function portraitSpec(typeId, present = PORTRAIT_LIST) {
  return portraitFor(typeId, undefined, present);
}

/**
 * The shopkeeper's portrait: the image, or a stamp on a warm brown disc.
 * @param {readonly string[]} [present]  the portrait ids that exist
 * @returns {PortraitSpec}
 */
export function shopkeeperSpec(present = PORTRAIT_LIST) {
  const alt = `${SHOPKEEPER.name}, the keeper of the trading post`;
  const spec = portraitFor(SHOPKEEPER.id, undefined, present);
  return spec.kind === 'image' ? { ...spec, alt } : { ...spec, alt };
}

const CLIP_ID = 'ug-portrait-clip';
const MOOD_SUFFIX = new RegExp(`-(${PORTRAIT_MOODS.join('|')})$`);

/**
 * The portrait id an href names: 'assets/portraits/fox-happy.webp' is
 * 'fox-happy'.
 * @param {string} href
 * @returns {string}
 */
function stemOf(href) {
  const file = href.split('/').pop() ?? href;
  return file.replace(/\.[^.]*$/, '');
}

/**
 * The character id behind a portrait href, mood or blink stripped.
 * @param {string} href
 * @returns {string}
 */
function idFromHref(href) {
  const stem = stemOf(href);
  return (stem.endsWith(BLINK_SUFFIX) ? stem.slice(0, -BLINK_SUFFIX.length) : stem).replace(MOOD_SUFFIX, '');
}

/**
 * The blink frame to stack over a portrait on screen, or null. Only a
 * plain portrait blinks, and only when its blink frame exists: a mood
 * portrait has no closed-eyes frame, nor has a stamp.
 * @param {PortraitSpec|null} spec  what is shown
 * @param {readonly string[]} [present]  the portrait ids that exist
 * @returns {string|null}  the blink frame's href
 */
export function blinkFor(spec, present = PORTRAIT_LIST) {
  if (spec === null || spec.kind !== 'image') return null;
  const stem = stemOf(spec.href);
  if (stem !== idFromHref(spec.href) || !present.includes(stem)) return null;
  return present.includes(`${stem}${BLINK_SUFFIX}`) ? portraitFile(`${stem}${BLINK_SUFFIX}`) : null;
}

/**
 * Draws a stamp disc of radius `r` centred on (cx, cy).
 * @param {Element} parent
 * @param {Extract<PortraitSpec, {kind: 'stamp'}>} spec
 * @param {number} cx
 * @param {number} cy
 * @param {number} r
 * @returns {void}
 */
function drawStampDisc(parent, spec, cx, cy, r) {
  el('circle', { cx, cy, r, fill: spec.disc, stroke: spec.rim, 'stroke-width': Math.max(2, r * 0.09) }, parent);
  el('circle', { cx: cx - r * 0.35, cy: cy - r * 0.4, r: r * 0.22, fill: CREAM, opacity: 0.18 }, parent);
}

/**
 * Draws a stamp's glyph — the silhouette, or the plain glyph where
 * there is no canvas — centred on (cx, cy).
 * @param {Element} parent
 * @param {Extract<PortraitSpec, {kind: 'stamp'}>} spec
 * @param {number} cx
 * @param {number} cy
 * @param {number} r
 * @returns {void}
 */
function drawStampGlyph(parent, spec, cx, cy, r) {
  const url = silhouettes.url(spec.glyph);
  const s = r * 1.25;
  if (url !== null) {
    el('image', { href: url, x: cx - s / 2, y: cy - s / 2, width: s, height: s, 'data-glyph': spec.glyph }, parent);
  } else {
    const t = el('text', {
      x: cx, y: cy + r * 0.34, 'text-anchor': 'middle', 'font-size': r, 'data-glyph': spec.glyph,
    }, parent);
    t.textContent = spec.glyph;
  }
}

/**
 * Draws a whole stamp: its disc, then its glyph.
 * @param {Element} parent
 * @param {Extract<PortraitSpec, {kind: 'stamp'}>} spec
 * @param {number} cx
 * @param {number} cy
 * @param {number} r
 * @returns {void}
 */
function drawStamp(parent, spec, cx, cy, r) {
  drawStampDisc(parent, spec, cx, cy, r);
  drawStampGlyph(parent, spec, cx, cy, r);
}

/**
 * Draws a portrait as a disc of radius `r` centred on (cx, cy), inside any
 * SVG element. An image fills the circle (cover, centred, clipped round)
 * with the character's name as its label, over the stamp's plain disc:
 * if the image fails to load it is taken away and the stamp shows
 * instead.
 * @param {Element} parent
 * @param {PortraitSpec} spec
 * @param {number} cx
 * @param {number} cy
 * @param {number} r
 * @returns {SVGElement}
 */
export function drawPortrait(parent, spec, cx, cy, r) {
  const g = el('g', { 'data-portrait': spec.kind }, parent);
  if (spec.kind === 'image') {
    const title = el('title', {}, g);
    title.textContent = spec.alt;
    // objectBoundingBox units: the same clip fits every portrait, so a
    // repeated id on the page is harmless.
    const clip = el('clipPath', { id: CLIP_ID, clipPathUnits: 'objectBoundingBox' }, g);
    el('circle', { cx: 0.5, cy: 0.5, r: 0.5 }, clip);
    el('circle', { cx, cy, r: r + 1.5, fill: SOIL_DARK }, g);
    // Under the image, the stamp's plain disc: mood portraits are
    // transparent cutouts, so the disc is their backdrop. The glyph is
    // only drawn if the image fails, so no silhouette peeks through.
    const fallback = stampFor(idFromHref(spec.href), spec.alt);
    if (fallback.kind === 'stamp') drawStampDisc(g, fallback, cx, cy, r);
    const under = el('g', { 'data-fallback': 'stamp' }, g);
    const image = el('image', {
      href: spec.href, x: cx - r, y: cy - r, width: r * 2, height: r * 2,
      preserveAspectRatio: 'xMidYMid slice', 'clip-path': `url(#${CLIP_ID})`,
    }, g);
    image.addEventListener('error', () => {
      image.remove();
      if (fallback.kind === 'stamp') drawStampGlyph(under, fallback, cx, cy, r);
    });
    return g;
  }
  drawStamp(g, spec, cx, cy, r);
  return g;
}

/**
 * A portrait on its own: a square <svg> holding one disc.
 * @param {PortraitSpec} spec
 * @param {string} [className]
 * @returns {SVGElement}
 */
export function portraitSvg(spec, className = 'portrait') {
  const svg = el('svg', { viewBox: '0 0 64 64', class: className, role: 'img', 'aria-label': spec.alt });
  drawPortrait(svg, spec, 32, 32, 30);
  return svg;
}

/**
 * Who speaks a scene line (opening-act spec, "The scene system"): the name
 * shown and the portrait. A band type speaks under its own name; `hazel` is
 * the shopkeeper; `narrator` has neither name nor portrait; any other id is
 * named by the id itself and has no stamp.
 *
 * The portrait is portraitFor's: `${id}-${mood}` when that image is in
 * `present`, else the plain `id` image when that is, else the stamp. So a
 * scene, a unit card and the shop show the same images. Hazel's images
 * are the shopkeeper's.
 * @param {string} who  a band type id, 'hazel' or 'narrator'
 * @param {string} [mood]  one of PORTRAIT_MOODS
 * @param {readonly string[]} [present]  the ids of the portrait images that exist
 * @returns {{name: string, portrait: PortraitSpec|null}}
 */
export function speakerSpec(who, mood, present = PORTRAIT_LIST) {
  if (who === 'narrator') return { name: '', portrait: null };
  if (who === 'hazel') {
    const alt = shopkeeperSpec(present).alt;
    return { name: SHOPKEEPER.name, portrait: { ...portraitFor(SHOPKEEPER.id, mood, present), alt } };
  }
  const def = BAND_TYPES[who];
  const portrait = portraitFor(who, mood, present);
  if (def === undefined) return { name: who, portrait: portrait.kind === 'image' ? portrait : null };
  return { name: def.name, portrait };
}

/**
 * Where each character's head is in its portrait, for the small round
 * heads on the deploy screen's roster: the centre and the side of a
 * square around it, as shares of the portrait's side. Measured on the
 * seated portraits (scripts/portraits.mjs); a mood portrait shares its
 * character's. A character not listed gets DEFAULT_HEAD.
 * @typedef {{x: number, y: number, size: number}} HeadCrop
 */
/** @type {Readonly<Record<string, HeadCrop>>} */
export const HEAD_CROPS = Object.freeze({
  fox: { x: 0.44, y: 0.46, size: 0.54 },
  hedgehog: { x: 0.35, y: 0.45, size: 0.58 },
  // The face, with the roots of the antennae: centred on the antennae
  // (as measured) the face sat low in the window, its jaws cut off.
  ants: { x: 0.485, y: 0.45, size: 0.46 },
  badger: { x: 0.42, y: 0.36, size: 0.5 },
  beaver: { x: 0.40, y: 0.34, size: 0.5 },
  bear: { x: 0.45, y: 0.36, size: 0.5 },
  owl: { x: 0.5, y: 0.33, size: 0.5 },
  bees: { x: 0.45, y: 0.84, size: 0.3 },
  shopkeeper: { x: 0.45, y: 0.40, size: 0.45 },
});

/** The top middle of a bust, where most heads are. */
export const DEFAULT_HEAD = Object.freeze({ x: 0.5, y: 0.38, size: 0.55 });

/**
 * @param {string} id  a character id
 * @returns {HeadCrop}
 */
export function headCrop(id) {
  return HEAD_CROPS[id] ?? DEFAULT_HEAD;
}

/**
 * How to place a whole portrait inside a round window so only its head
 * shows: the image's width and offsets, in percent of the window.
 * @param {HeadCrop} crop
 * @returns {{width: string, left: string, top: string}}
 */
export function headCropStyle(crop) {
  const pct = (/** @type {number} */ n) => `${Math.round(n * 1000) / 10}%`;
  return {
    width: pct(1 / crop.size),
    left: pct((crop.size / 2 - crop.x) / crop.size),
    top: pct((crop.size / 2 - crop.y) / crop.size),
  };
}
